n = int(input())
valid = {input() for _ in range(n)}
known = {word.lower() for word in valid}
errors = 0
for word in input().split():
    if word.lower() in known:
        errors += word not in valid
    else:
        errors += sum(c.isupper() for c in word) != 1
print(errors)

