n = int(input())
positions = {}
for _ in range(n):
    word = input()
    index = next(i for i, c in enumerate(word) if c.isupper())
    positions.setdefault(word.lower(), set()).add(index)
errors = 0
for word in input().split():
    stress = [i for i, c in enumerate(word) if c.isupper()]
    if len(stress) != 1:
        errors += 1
    elif word.lower() in positions and stress[0] not in positions[word.lower()]:
        errors += 1
print(errors)
